mapper.select:
SELECT * FROM fulfillments

    status = #{status}

ORDER BY updated_at ASC
LIMIT #{limit}

mapper.update:
UPDATE fulfillments
SET status = #{status}, reviewed_at = #{reviewedAt}, delivered_at = #{deliveredAt}, updated_at = #{updatedAt}
WHERE id = #{id} AND status = 'AWAITING_REVIEW'

UPDATE fulfillments
SET operator_id = NULL, claimed_at = NULL, status = 'MANUAL_PENDING', updated_at = #{updatedAt}
WHERE status = 'CLAIMED' AND claimed_at < #{cutoff}
